Here is the root cause:
The v11 MQD manager incorrectly assigned the CP-compute variants of checkpoint_mqd and restore_mqd to KFD_MQD_TYPE_SDMA queues. These functions operate on the larger `struct v11_compute_mqd` (2048 bytes), but SDMA queues use the smaller `struct v11_sdma_mqd` (512 bytes), causing a 1536-byte buffer overflow during checkpoint (memory leak) and restore (memory corruption).

Here is the patch:

 static void restore_mqd(struct mqd_manager *mm, void **mqd,
 			struct kfd_mem_obj *mqd_mem_obj, uint64_t *gart_addr,
-			struct queue_properties *qp,
-			const void *mqd_src,
+			struct queue_properties *qp, const void *mqd_src,
 			const void *ctl_stack_src, const u32 ctl_stack_size)
 {
 	uint64_t addr;
 	struct v11_compute_mqd *m;

 	m = (struct v11_compute_mqd *) mqd_mem_obj->cpu_ptr;
 	addr = mqd_mem_obj->gpu_addr;

 	memcpy(m, mqd_src, sizeof(*m));

 	*mqd = m;
 	if (gart_addr)
 		*gart_addr = addr;

 	m->cp_hqd_pq_doorbell_control =
-		qp->doorbell_off <<
-			CP_HQD_PQ_DOORBELL_CONTROL__DOORBELL_OFFSET__SHIFT;
-	pr_debug("cp_hqd_pq_doorbell_control 0x%x\n",
-			m->cp_hqd_pq_doorbell_control);
+		qp->doorbell_off << CP_HQD_PQ_DOORBELL_CONTROL__DOORBELL_OFFSET__SHIFT;
+	pr_debug("cp_hqd_pq_doorbell_control 0x%x\n", m->cp_hqd_pq_doorbell_control);

 	qp->is_active = 0;
 }

